import { describe, expect, it } from "vitest";

import { getPath, setPath } from "./path.js";

describe("getPath", () => {
  it("reads nested dot-paths", () => {
    expect(getPath({ actor: { name: "Ada" }, items: ["a"] }, "actor.name")).toBe("Ada");
    expect(getPath({ items: ["a", "b"] }, "items.0")).toBe("a");
  });

  it("returns null when a path is missing", () => {
    expect(getPath({}, "missing")).toBeNull();
    expect(getPath({ actor: { name: "Ada" } }, "actor.id")).toBeNull();
    expect(getPath({ actor: null }, "actor.name")).toBeNull();
  });

  it("returns null for an explicit null value", () => {
    expect(getPath({ actor: null }, "actor")).toBeNull();
  });

  it("does not read inherited properties", () => {
    expect(getPath({}, "constructor")).toBeNull();
    expect(getPath({}, "toString")).toBeNull();
  });
});

describe("setPath", () => {
  it("writes a nested path without mutating the input", () => {
    const input = { type: "lock.unlock" };
    const next = setPath(input, "actor.name", "Ada");
    expect(next).toEqual({ type: "lock.unlock", actor: { name: "Ada" } });
    expect(input).toEqual({ type: "lock.unlock" });
  });

  it("rejects a path through a primitive value", () => {
    expect(() => setPath({ actor: "Ada" }, "actor.name", "x")).toThrow(/cannot set path/);
  });

  it("stores __proto__ as an own property", () => {
    const next = setPath({}, "__proto__", { polluted: true });
    expect(Object.hasOwn(next, "__proto__")).toBe(true);
    expect(Object.prototype).not.toHaveProperty("polluted");
  });
});

import { describe, expect, it } from "vitest";

import { interpolate } from "./template.js";

describe("interpolate", () => {
  it("replaces a missing placeholder with an empty string", () => {
    expect(interpolate("Hello {{name}}", {})).toBe("Hello ");
    expect(interpolate("{{a}}-{{b}}", { a: "1" })).toBe("1-");
  });

  it("reads nested dot-paths and trims placeholder whitespace", () => {
    expect(interpolate("Event {{ type }} by {{actor.name}}", { type: "lock.unlock", actor: { name: "Ada" } })).toBe(
      "Event lock.unlock by Ada",
    );
  });

  it("stringifies numbers, booleans, and objects", () => {
    expect(interpolate("{{count}} {{ok}} {{meta}}", { count: 3, ok: false, meta: { a: 1 } })).toBe(
      '3 false {"a":1}',
    );
  });

  it("renders an explicit null as an empty string", () => {
    expect(interpolate("{{name}}", { name: null })).toBe("");
  });

  it("uses workflow_id and run_id bindings when those paths are absent", () => {
    expect(interpolate("{{workflow_id}}/{{run_id}}", {}, { workflow_id: "wf", run_id: "run" })).toBe("wf/run");
  });

  it("prefers a context value over a reserved binding", () => {
    expect(interpolate("{{workflow_id}}", { workflow_id: "from-ctx" }, { workflow_id: "from-binding" })).toBe(
      "from-ctx",
    );
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";

import { applyTransform } from "./transform.js";

describe("applyTransform", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("applies default, template, and pick in order", () => {
    const next = applyTransform(
      {
        type: "transform",
        ops: [
          { op: "default", path: "actor_name", value: "Unknown" },
          { op: "template", to: "title", template: "Event {{type}} by {{actor_name}}" },
          { op: "pick", paths: ["uuid", "type", "success", "severity", "title"] },
        ],
      },
      { uuid: "abc", type: "lock.unlock", success: false, severity: null },
    );

    expect(next).toEqual({
      uuid: "abc",
      type: "lock.unlock",
      success: false,
      severity: null,
      title: "Event lock.unlock by Unknown",
    });
  });

  it("does not replace an existing default value", () => {
    const next = applyTransform(
      {
        type: "transform",
        ops: [{ op: "default", path: "success", value: true }],
      },
      { success: false },
    );
    expect(next).toEqual({ success: false });
  });

  it("fills null and missing paths", () => {
    const next = applyTransform(
      {
        type: "transform",
        ops: [
          { op: "default", path: "success", value: true },
          { op: "default", path: "actor.name", value: "Unknown" },
        ],
      },
      { success: null },
    );
    expect(next).toEqual({ success: true, actor: { name: "Unknown" } });
  });

  it("renders missing template values as empty strings", () => {
    const next = applyTransform(
      {
        type: "transform",
        ops: [{ op: "template", to: "title", template: "Hello {{name}}" }],
      },
      {},
    );
    expect(next).toEqual({ title: "Hello " });
  });

  it("does not mutate the input or perform external side effects", () => {
    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);
    const actor = { name: "Ada" };
    const input = { type: "lock.unlock", actor };
    const next = applyTransform(
      {
        type: "transform",
        ops: [{ op: "template", to: "title", template: "Event {{type}} by {{actor.name}}" }],
      },
      input,
    );

    expect(next).toEqual({
      type: "lock.unlock",
      actor: { name: "Ada" },
      title: "Event lock.unlock by Ada",
    });
    expect(input).toEqual({ type: "lock.unlock", actor: { name: "Ada" } });
    expect(input.actor).toBe(actor);
    expect(fetchMock).not.toHaveBeenCalled();
  });
});

import { describe, expect, it } from "vitest";

import { filterMatches } from "./filter.js";

const andStep = {
  type: "filter" as const,
  conditions: [
    { path: "type", op: "eq" as const, value: "lock.unlock" },
    { path: "success", op: "neq" as const, value: true },
  ],
};

describe("filterMatches", () => {
  it("passes when every condition matches", () => {
    expect(filterMatches(andStep, { type: "lock.unlock", success: false })).toBe(true);
  });

  it("fails when one AND condition does not match", () => {
    expect(filterMatches(andStep, { type: "lock.unlock", success: true })).toBe(false);
    expect(filterMatches(andStep, { type: "lock.lock", success: false })).toBe(false);
  });

  it("compares a missing path as null", () => {
    expect(
      filterMatches(
        { type: "filter", conditions: [{ path: "actor", op: "eq", value: null }] },
        {},
      ),
    ).toBe(true);
    expect(
      filterMatches(
        { type: "filter", conditions: [{ path: "actor", op: "eq", value: "Ada" }] },
        {},
      ),
    ).toBe(false);
  });

  it("deep-equals object values", () => {
    expect(
      filterMatches(
        { type: "filter", conditions: [{ path: "meta", op: "eq", value: { b: 1, a: 2 } }] },
        { meta: { a: 2, b: 1 } },
      ),
    ).toBe(true);
  });

  it("does not mutate the context", () => {
    const nested = { ok: true };
    const ctx = { type: "lock.unlock", success: false, nested };
    expect(filterMatches(andStep, ctx)).toBe(true);
    expect(ctx).toEqual({ type: "lock.unlock", success: false, nested });
    expect(ctx.nested).toBe(nested);
  });
});

import type { HttpRequestStep, JsonObject } from "@kisi-workflow/shared";
import { describe, expect, it, vi } from "vitest";

import { executeHttpRequest, httpRetryDelayMs } from "./http-request.js";
import { StepFailedError } from "./errors.js";

const workflowId = "22222222-2222-4222-8222-222222222222";

function step(overrides: Partial<HttpRequestStep> = {}): HttpRequestStep {
  return {
    type: "http_request",
    method: "POST",
    url: "https://alerts.example.com/hook",
    timeoutMs: 1000,
    retries: 0,
    ...overrides,
  };
}

function jsonResponse(status: number, body = ""): Response {
  return new Response(body, { status });
}

function hangingFetch(): typeof fetch {
  return ((_url: string, init?: RequestInit) =>
    new Promise((_resolve, reject) => {
      const signal = init?.signal;
      if (!signal) {
        reject(new Error("missing abort signal"));
        return;
      }
      const abort = () => {
        const error = new Error("The operation was aborted");
        error.name = "AbortError";
        reject(error);
      };
      if (signal.aborted) {
        abort();
        return;
      }
      signal.addEventListener("abort", abort, { once: true });
    })) as typeof fetch;
}

describe("httpRetryDelayMs", () => {
  it("uses exponential backoff capped at 4000ms", () => {
    expect(httpRetryDelayMs(0, () => 0)).toBe(1000);
    expect(httpRetryDelayMs(1, () => 0)).toBe(2000);
    expect(httpRetryDelayMs(2, () => 0)).toBe(4000);
    expect(httpRetryDelayMs(4, () => 0)).toBe(4000);
  });

  it("adds jitter in the range 0 to 100ms", () => {
    expect(httpRetryDelayMs(0, () => 0)).toBe(1000);
    expect(httpRetryDelayMs(0, () => 0.999)).toBe(1100);
  });
});

describe("executeHttpRequest", () => {
  it("sends the configured method, url, interpolated headers, and context body", async () => {
    const ctx: JsonObject = { type: "lock.unlock", success: false };
    const fetchMock = vi.fn(async () => jsonResponse(200));
    await executeHttpRequest(step({
      headers: {
        "Content-Type": "application/json",
        "X-Workflow-Id": "{{workflow_id}}",
      },
      body: { mode: "ctx" },
    }), ctx, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
      bindings: { workflow_id: workflowId },
    });

    expect(fetchMock).toHaveBeenCalledTimes(1);
    const call = fetchMock.mock.calls[0];
    expect(call?.[0]).toBe("https://alerts.example.com/hook");
    expect(call?.[1]).toMatchObject({
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Workflow-Id": workflowId,
      },
      body: JSON.stringify(ctx),
      redirect: "manual",
    });
    expect(ctx).toEqual({ type: "lock.unlock", success: false });
  });

  it("interpolates a custom JSON body and leaves non-strings unchanged", async () => {
    const fetchMock = vi.fn(async () => jsonResponse(200));
    await executeHttpRequest(step({
      body: { mode: "custom", json: { content: "Alert {{title}}", n: 1 } },
    }), { title: "Door" }, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
    });

    expect(fetchMock.mock.calls[0]?.[1]).toMatchObject({
      body: JSON.stringify({ content: "Alert Door", n: 1 }),
    });
  });

  it("omits the body when the step has no body configuration", async () => {
    const fetchMock = vi.fn(async () => jsonResponse(204));
    await executeHttpRequest(step({ method: "GET" }), {}, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
    });
    expect(fetchMock.mock.calls[0]?.[1]?.method).toBe("GET");
    expect(fetchMock.mock.calls[0]?.[1]?.body).toBeUndefined();
  });

  it("forwards PUT, PATCH, and DELETE", async () => {
    for (const method of ["PUT", "PATCH", "DELETE"] as const) {
      const fetchMock = vi.fn(async () => jsonResponse(200));
      await executeHttpRequest(step({ method }), {}, {
        fetchImpl: fetchMock,
        sleep: async () => {},
        random: () => 0,
      });
      expect(fetchMock.mock.calls[0]?.[1]?.method).toBe(method);
    }
  });

  it("succeeds on HTTP 2xx without changing context", async () => {
    const ctx = { ok: true };
    const fetchMock = vi.fn(async () => jsonResponse(204));
    await expect(executeHttpRequest(step(), ctx, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
    })).resolves.toBeUndefined();
    expect(fetchMock).toHaveBeenCalledTimes(1);
    expect(ctx).toEqual({ ok: true });
  });

  it("retries HTTP 5xx and then succeeds", async () => {
    const sleep = vi.fn(async () => {});
    const fetchMock = vi.fn()
      .mockResolvedValueOnce(jsonResponse(500, "unavailable"))
      .mockResolvedValueOnce(jsonResponse(502, "bad gateway"))
      .mockResolvedValueOnce(jsonResponse(200));
    await executeHttpRequest(step({ retries: 2 }), {}, {
      fetchImpl: fetchMock,
      sleep,
      random: () => 0,
    });
    expect(fetchMock).toHaveBeenCalledTimes(3);
    expect(sleep.mock.calls).toEqual([[httpRetryDelayMs(0, () => 0)], [httpRetryDelayMs(1, () => 0)]]);
  });

  it("retries network failures and then succeeds", async () => {
    const fetchMock = vi.fn()
      .mockRejectedValueOnce(new Error("connect ECONNRESET"))
      .mockRejectedValueOnce(new Error("connect ECONNRESET"))
      .mockResolvedValueOnce(jsonResponse(200));
    await executeHttpRequest(step({ retries: 2 }), {}, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
    });
    expect(fetchMock).toHaveBeenCalledTimes(3);
  });

  it("does not retry HTTP 4xx", async () => {
    const sleep = vi.fn(async () => {});
    const fetchMock = vi.fn(async () => jsonResponse(400, "bad request"));
    await expect(executeHttpRequest(step({ retries: 5 }), {}, {
      fetchImpl: fetchMock,
      sleep,
      random: () => 0,
    })).rejects.toMatchObject({
      name: "StepFailedError",
      stepType: "http_request",
      httpStatus: 400,
      message: "HTTP 400: bad request",
    });
    expect(fetchMock).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });

  it("does not retry HTTP 429", async () => {
    const sleep = vi.fn(async () => {});
    const fetchMock = vi.fn(async () => jsonResponse(429, "slow down"));
    await expect(executeHttpRequest(step({ retries: 5 }), {}, {
      fetchImpl: fetchMock,
      sleep,
      random: () => 0,
    })).rejects.toMatchObject({
      httpStatus: 429,
      message: "HTTP 429: slow down",
    });
    expect(fetchMock).toHaveBeenCalledTimes(1);
    expect(sleep).not.toHaveBeenCalled();
  });

  it("fails a timeout after the configured retries", async () => {
    const sleep = vi.fn(async () => {});
    const fetchMock = vi.fn(hangingFetch());
    const error = await executeHttpRequest(step({ retries: 1, timeoutMs: 20 }), {}, {
      fetchImpl: fetchMock,
      sleep,
      random: () => 0,
    }).catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(StepFailedError);
    expect(error).toMatchObject({
      stepType: "http_request",
      message: "request timed out",
    });
    expect(error).not.toHaveProperty("httpStatus", expect.any(Number));
    expect(fetchMock).toHaveBeenCalledTimes(2);
    expect(sleep).toHaveBeenCalledTimes(1);
  });

  it("does not retry a blocked URL and does not call fetch", async () => {
    const fetchMock = vi.fn(async () => jsonResponse(200));
    await expect(executeHttpRequest(step({
      url: "http://127.0.0.1:9000/alerts",
      retries: 4,
    }), {}, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
    })).rejects.toMatchObject({
      stepType: "http_request",
      message: "blocked URL",
    });
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("performs a single attempt when retries is 0", async () => {
    const fetchMock = vi.fn(async () => jsonResponse(500, "down"));
    await expect(executeHttpRequest(step({ retries: 0 }), {}, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
    })).rejects.toMatchObject({ httpStatus: 500, message: "HTTP 500: down" });
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it("truncates an HTTP error body to 1024 characters", async () => {
    const body = "x".repeat(1200);
    const fetchMock = vi.fn(async () => jsonResponse(500, body));
    await expect(executeHttpRequest(step({ retries: 0 }), {}, {
      fetchImpl: fetchMock,
      sleep: async () => {},
      random: () => 0,
    })).rejects.toMatchObject({
      message: `HTTP 500: ${"x".repeat(1024)}`,
    });
  });
});

import { describe, expect, it } from "vitest";

import { assertOutboundUrl, SsrfBlockedError } from "./ssrf.js";

const blocked = [
  "http://localhost/admin",
  "http://LOCALHOST/admin",
  "http://127.0.0.1/admin",
  "http://127.255.255.255/admin",
  "http://10.1.2.3/admin",
  "http://172.16.0.1/admin",
  "http://172.31.255.255/admin",
  "http://192.168.1.20/admin",
  "http://169.254.169.254/latest",
  "http://[::1]/admin",
  "http://metadata.google.internal/computeMetadata/v1/",
];

describe("assertOutboundUrl", () => {
  it("allows public http and https URLs", () => {
    expect(assertOutboundUrl("https://alerts.example.com/hook").href).toBe("https://alerts.example.com/hook");
    expect(assertOutboundUrl("http://8.8.8.8/dns").hostname).toBe("8.8.8.8");
    expect(assertOutboundUrl("http://172.32.0.1/outside").hostname).toBe("172.32.0.1");
  });

  it("blocks private, loopback, link-local, and metadata hosts", () => {
    for (const url of blocked) {
      expect(() => assertOutboundUrl(url)).toThrow(SsrfBlockedError);
    }
  });

  it("blocks non-http protocols", () => {
    expect(() => assertOutboundUrl("ftp://alerts.example.com/hook")).toThrow(SsrfBlockedError);
  });

  it("blocks an unparseable URL", () => {
    expect(() => assertOutboundUrl("not a url")).toThrow(SsrfBlockedError);
  });

  it("allows private hosts only when the override is enabled", () => {
    expect(assertOutboundUrl("http://127.0.0.1:9000/alerts", true).hostname).toBe("127.0.0.1");
  });

  it("still blocks non-http protocols when the private-host override is enabled", () => {
    expect(() => assertOutboundUrl("ftp://127.0.0.1/alerts", true)).toThrow(SsrfBlockedError);
  });
});

import { WorkflowRunSchema } from "@kisi-workflow/shared";
import type { WorkflowStep } from "@kisi-workflow/shared";
import { describe, expect, it, vi } from "vitest";

import { InMemoryWorkflowRunRepository } from "../db/in-memory-workflow-run-repository.js";
import { EngineValidationError } from "./errors.js";
import { executeWorkflow } from "./runner.js";
import type { ExecuteWorkflowDeps } from "./runner.js";

const WORKFLOW_ID = "22222222-2222-4222-8222-222222222222";
const RUN_ID = "11111111-1111-4111-8111-111111111111";
const STARTED_AT = "2026-09-23T00:00:00.000Z";
const FINISHED_AT = "2026-09-23T00:00:01.000Z";

function sequentialClock(times: readonly Date[]): () => Date {
  let index = 0;
  return () => {
    const current = times[index];
    if (current === undefined) {
      const last = times[times.length - 1];
      if (last === undefined) {
        throw new Error("clock has no times");
      }
      return last;
    }
    if (index < times.length - 1) {
      index += 1;
    }
    return current;
  };
}

function setup(respond?: () => Promise<Response>): {
  repo: InMemoryWorkflowRunRepository;
  fetchMock: ReturnType<typeof vi.fn<typeof fetch>>;
  deps: ExecuteWorkflowDeps;
} {
  const repo = new InMemoryWorkflowRunRepository();
  const fetchMock = vi.fn<typeof fetch>(respond ?? (async () => new Response(null, { status: 200 })));
  const deps: ExecuteWorkflowDeps = {
    runRepository: repo,
    fetchImpl: fetchMock,
    now: sequentialClock([new Date(STARTED_AT), new Date(FINISHED_AT)]),
    sleep: async () => {},
    random: () => 0,
    generateId: () => RUN_ID,
  };
  return { repo, fetchMock, deps };
}

const passingFilter: WorkflowStep = {
  type: "filter",
  conditions: [
    { path: "type", op: "eq", value: "lock.unlock" },
    { path: "success", op: "eq", value: false },
  ],
};

const titleTransform: WorkflowStep = {
  type: "transform",
  ops: [
    { op: "default", path: "actor_name", value: "Unknown" },
    { op: "template", to: "title", template: "Event {{type}} by {{actor_name}}" },
  ],
};

function httpStep(url: string): WorkflowStep {
  return {
    type: "http_request",
    method: "POST",
    url,
    headers: { "X-Workflow-Id": "{{workflow_id}}", "X-Title": "{{title}}" },
    body: { mode: "ctx" },
    timeoutMs: 1000,
    retries: 0,
  };
}

describe("executeWorkflow", () => {
  it("succeeds an empty workflow", async () => {
    const { deps } = setup();
    const run = await executeWorkflow(
      { workflowId: WORKFLOW_ID, steps: [], requestBody: { ok: true } },
      deps,
    );
    expect(run.status).toBe("success");
    expect(run.error).toBeNull();
    expect(run.finalCtx).toEqual({ ok: true });
  });

  it("persists a successful empty workflow", async () => {
    const { deps, repo } = setup();
    const requestBody = { ok: true };
    const run = await executeWorkflow(
      { workflowId: WORKFLOW_ID, steps: [], requestBody },
      deps,
    );

    expect(WorkflowRunSchema.safeParse(run).success).toBe(true);
    expect(run).toMatchObject({
      id: RUN_ID,
      workflowId: WORKFLOW_ID,
      status: "success",
      error: null,
      startedAt: STARTED_AT,
      finishedAt: FINISHED_AT,
      requestBody,
      finalCtx: requestBody,
    });
    expect(repo.snapshot()).toEqual([run]);
    expect(requestBody).toEqual({ ok: true });
  });

  it("applies a transform step to the execution context", async () => {
    const { deps } = setup();
    const run = await executeWorkflow(
      {
        workflowId: WORKFLOW_ID,
        steps: [titleTransform],
        requestBody: { type: "lock.unlock" },
      },
      deps,
    );
    expect(run.status).toBe("success");
    expect(run.finalCtx).toEqual({
      type: "lock.unlock",
      actor_name: "Unknown",
      title: "Event lock.unlock by Unknown",
    });
    expect(run.requestBody).toEqual({ type: "lock.unlock" });
  });

  it("continues when every filter condition matches", async () => {
    const { deps } = setup();
    const run = await executeWorkflow(
      {
        workflowId: WORKFLOW_ID,
        steps: [passingFilter, titleTransform],
