import type { WorkflowStepType } from "@kisi-workflow/shared";

export class EngineValidationError extends Error {
  constructor() {
    super("invalid workflow execution input");
    this.name = "EngineValidationError";
  }
}

export class StepFailedError extends Error {
  readonly stepType: WorkflowStepType;
  readonly httpStatus: number | undefined;

  constructor(stepType: WorkflowStepType, message: string, httpStatus?: number) {
    super(message);
    this.name = "StepFailedError";
    this.stepType = stepType;
    this.httpStatus = httpStatus;
  }
}

import type { JsonObject } from "@kisi-workflow/shared";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function assignOwn(target: Record<string, unknown>, key: string, value: unknown): void {
  Object.defineProperty(target, key, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
}

function segmentsOf(path: string): string[] {
  return path.split(".");
}

export function getPath(ctx: JsonObject, path: string): unknown {
  const segments = segmentsOf(path);
  let current: unknown = ctx;
  for (const segment of segments) {
    if (segment.length === 0) {
      return null;
    }
    if (Array.isArray(current)) {
      if (!Object.hasOwn(current, segment)) {
        return null;
      }
      const index = Number(segment);
      if (!Number.isInteger(index) || String(index) !== segment) {
        return null;
      }
      const value: unknown = current[index];
      current = value === undefined ? null : value;
      continue;
    }
    if (!isRecord(current) || !Object.hasOwn(current, segment)) {
      return null;
    }
    const value = current[segment];
    current = value === undefined ? null : value;
  }
  return current === undefined ? null : current;
}

export function hasPath(ctx: JsonObject, path: string): boolean {
  const segments = segmentsOf(path);
  let current: unknown = ctx;
  for (const segment of segments) {
    if (segment.length === 0) {
      return false;
    }
    if (Array.isArray(current)) {
      if (!Object.hasOwn(current, segment)) {
        return false;
      }
      const index = Number(segment);
      if (!Number.isInteger(index) || String(index) !== segment) {
        return false;
      }
      current = current[index];
      continue;
    }
    if (!isRecord(current) || !Object.hasOwn(current, segment)) {
      return false;
    }
    current = current[segment];
  }
  return true;
}

export function setPath(ctx: JsonObject, path: string, value: unknown): JsonObject {
  const segments = segmentsOf(path);
  if (segments.length === 0 || segments.some((segment) => segment.length === 0)) {
    throw new Error(`cannot set path "${path}"`);
  }

  const cloned: unknown = structuredClone(ctx);
  if (!isRecord(cloned)) {
    throw new Error(`cannot set path "${path}"`);
  }

  let current = cloned;
  for (let index = 0; index < segments.length - 1; index += 1) {
    const segment = segments[index];
    if (segment === undefined) {
      throw new Error(`cannot set path "${path}"`);
    }
    const existing = Object.hasOwn(current, segment) ? current[segment] : undefined;
    if (existing === undefined || existing === null) {
      const created: Record<string, unknown> = {};
      assignOwn(current, segment, created);
      current = created;
      continue;
    }
    if (!isRecord(existing)) {
      throw new Error(`cannot set path "${path}"`);
    }
    current = existing;
  }

  const last = segments[segments.length - 1];
  if (last === undefined) {
    throw new Error(`cannot set path "${path}"`);
  }
  assignOwn(current, last, value);
  return cloned;
}

import type { JsonObject } from "@kisi-workflow/shared";

import { getPath, hasPath } from "./path.js";

export type TemplateBindings = {
  workflow_id?: string;
  run_id?: string;
};

function stringifyValue(value: unknown): string {
  if (value === null || value === undefined) {
    return "";
  }
  if (typeof value === "string") {
    return value;
  }
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  return JSON.stringify(value);
}

export function interpolate(template: string, ctx: JsonObject, bindings: TemplateBindings = {}): string {
  const placeholder = /\{\{\s*([^{}]+?)\s*\}\}/g;
  return template.replace(placeholder, (_match: string, rawPath: string) => {
    const path = rawPath.trim();
    if (!hasPath(ctx, path)) {
      if (path === "workflow_id" && bindings.workflow_id !== undefined) {
        return bindings.workflow_id;
      }
      if (path === "run_id" && bindings.run_id !== undefined) {
        return bindings.run_id;
      }
      return "";
    }
    return stringifyValue(getPath(ctx, path));
  });
}

import type { JsonObject, TransformStep } from "@kisi-workflow/shared";

import { getPath, setPath } from "./path.js";
import { interpolate, type TemplateBindings } from "./template.js";

export function applyTransform(
  step: TransformStep,
  ctx: JsonObject,
  bindings?: TemplateBindings,
): JsonObject {
  let current = ctx;
  for (const op of step.ops) {
    if (op.op === "default") {
      if (getPath(current, op.path) === null) {
        current = setPath(current, op.path, op.value);
      }
      continue;
    }
    if (op.op === "template") {
      current = setPath(current, op.to, interpolate(op.template, current, bindings));
      continue;
    }
    if (op.op === "pick") {
      let picked: JsonObject = {};
      for (const path of op.paths) {
        picked = setPath(picked, path, getPath(current, path));
      }
      current = picked;
      continue;
    }
    const unexpected: never = op;
    throw new Error(`unknown transform op: ${JSON.stringify(unexpected)}`);
  }
  return current;
}

import type { FilterStep, JsonObject } from "@kisi-workflow/shared";

import { getPath } from "./path.js";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function jsonEqual(left: unknown, right: unknown): boolean {
  if (left === right) {
    return true;
  }
  if (left === null || right === null || left === undefined || right === undefined) {
    return false;
  }
  if (typeof left !== typeof right) {
    return false;
  }
  if (Array.isArray(left) || Array.isArray(right)) {
    if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) {
      return false;
    }
    for (let index = 0; index < left.length; index += 1) {
      if (!jsonEqual(left[index], right[index])) {
        return false;
      }
    }
    return true;
  }
  if (!isRecord(left) || !isRecord(right)) {
    return false;
  }
  const leftKeys = Object.keys(left);
  if (leftKeys.length !== Object.keys(right).length) {
    return false;
  }
  return leftKeys.every((key) => Object.hasOwn(right, key) && jsonEqual(left[key], right[key]));
}

export function filterMatches(step: FilterStep, ctx: JsonObject): boolean {
  return step.conditions.every((condition) => {
    const actual = getPath(ctx, condition.path);
    const equal = jsonEqual(actual, condition.value);
    return condition.op === "eq" ? equal : !equal;
  });
}

export class SsrfBlockedError extends Error {
  constructor() {
    super("blocked URL");
    this.name = "SsrfBlockedError";
  }
}

const BLOCKED_HOSTS = new Set(["localhost", "metadata.google.internal"]);

function normalizeHost(hostname: string): string {
  let host = hostname.toLowerCase();
  if (host.startsWith("[") && host.endsWith("]")) {
    host = host.slice(1, -1);
  }
  if (host.endsWith(".")) {
    host = host.slice(0, -1);
  }
  return host;
}

function isPrivateIpv4(host: string): boolean {
  const parts = host.split(".");
  if (parts.length !== 4) {
    return false;
  }
  const numbers: number[] = [];
  for (const part of parts) {
    if (!/^\d{1,3}$/.test(part)) {
      return false;
    }
    const value = Number(part);
    if (!Number.isInteger(value) || value < 0 || value > 255) {
      return false;
    }
    numbers.push(value);
  }
  const first = numbers[0];
  const second = numbers[1];
  if (first === undefined || second === undefined) {
    return false;
  }
  if (first === 127 || first === 10) {
    return true;
  }
  if (first === 192 && second === 168) {
    return true;
  }
  if (first === 169 && second === 254) {
    return true;
  }
  return first === 172 && second >= 16 && second <= 31;
}

export function assertOutboundUrl(url: string, allowPrivateUrls = false): URL {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new SsrfBlockedError();
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new SsrfBlockedError();
  }
  if (allowPrivateUrls) {
    return parsed;
  }
  const host = normalizeHost(parsed.hostname);
  if (BLOCKED_HOSTS.has(host) || host === "::1" || isPrivateIpv4(host)) {
    throw new SsrfBlockedError();
  }
  return parsed;
}

import type { WorkflowRun } from "@kisi-workflow/shared";

export type NewWorkflowRun = Omit<WorkflowRun, "createdAt">;

export interface WorkflowRunRepository {
