  });
}

export function httpRetryDelayMs(attempt: number, random: () => number): number {
  const base = Math.min(1000 * 2 ** attempt, 4000);
  const jitter = Math.min(100, Math.floor(random() * 101));
  return base + jitter;
}

function isAbortError(error: unknown): boolean {
  return error instanceof Error && (error.name === "AbortError" || error.name === "TimeoutError");
}

function httpMessage(status: number, body: string): string {
  const truncated = body.slice(0, HTTP_ERROR_BODY_MAX);
  if (truncated.length === 0) {
    return `HTTP ${status}`;
  }
  return `HTTP ${status}: ${truncated}`;
}

function interpolateJson(value: unknown, ctx: JsonObject, bindings?: TemplateBindings): unknown {
  if (typeof value === "string") {
    return interpolate(value, ctx, bindings);
  }
  if (Array.isArray(value)) {
    return value.map((item) => interpolateJson(item, ctx, bindings));
  }
  if (isRecord(value)) {
    const next: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(value)) {
      next[key] = interpolateJson(child, ctx, bindings);
    }
    return next;
  }
  return value;
}

function requestBody(step: HttpRequestStep, ctx: JsonObject, bindings?: TemplateBindings): string | undefined {
  if (!step.body) {
    return undefined;
  }
  if (step.body.mode === "ctx") {
    return JSON.stringify(ctx);
  }
  return JSON.stringify(interpolateJson(step.body.json, ctx, bindings));
}

async function readBody(response: Response): Promise<string> {
  try {
    return await response.text();
  } catch {
    return "";
  }
}

async function fetchWithTimeout(
  step: HttpRequestStep,
  ctx: JsonObject,
  deps: HttpExecutorDeps,
  timeoutMs: number,
): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const init: RequestInit = {
      method: step.method,
      redirect: "manual",
      signal: controller.signal,
    };
    if (step.headers) {
      const headers: Record<string, string> = {};
      for (const [key, value] of Object.entries(step.headers)) {
        headers[key] = interpolate(value, ctx, deps.bindings);
      }
      init.headers = headers;
    }
    const body = requestBody(step, ctx, deps.bindings);
    if (body !== undefined) {
      init.body = body;
    }
    return await deps.fetchImpl(step.url, init);
  } finally {
    clearTimeout(timer);
  }
}

export async function executeHttpRequest(
  step: HttpRequestStep,
  ctx: JsonObject,
  deps: HttpExecutorDeps,
): Promise<void> {
  const retries = Math.min(Math.max(step.retries, HTTP_RETRIES_MIN), HTTP_RETRIES_MAX);
  const timeoutMs = Math.min(Math.max(step.timeoutMs, HTTP_TIMEOUT_MS_MIN), HTTP_TIMEOUT_MS_MAX);
  const sleep = deps.sleep ?? delay;
  const random = deps.random ?? Math.random;
  const allowPrivateUrls = deps.allowPrivateUrls ?? false;
  let lastFailure = new StepFailedError("http_request", "network error");

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    if (deps.deadlineAt !== undefined && deps.now !== undefined && deps.now().getTime() >= deps.deadlineAt) {
      throw new StepFailedError("http_request", "workflow time limit exceeded");
    }

    try {
      assertOutboundUrl(step.url, allowPrivateUrls);
    } catch (error) {
      if (error instanceof SsrfBlockedError) {
        throw new StepFailedError("http_request", "blocked URL");
      }
      throw error;
    }

    try {
      const response = await fetchWithTimeout(step, ctx, deps, timeoutMs);
      if (response.status >= 200 && response.status < 300) {
        return;
      }
      const body = await readBody(response);
      const failure = new StepFailedError("http_request", httpMessage(response.status, body), response.status);
      if (response.status < 500 || response.status > 599) {
        throw failure;
      }
      lastFailure = failure;
    } catch (error) {
      if (error instanceof StepFailedError) {
        throw error;
      }
      const message = isAbortError(error)
        ? "request timed out"
        : error instanceof Error && error.message.length > 0
          ? error.message
          : "network error";
      lastFailure = new StepFailedError("http_request", message);
    }

    if (attempt < retries) {
      await sleep(httpRetryDelayMs(attempt, random));
    }
  }

  throw lastFailure;
}

import { randomUUID } from "node:crypto";

import { JsonObjectSchema, WorkflowStepsSchema } from "@kisi-workflow/shared";
import type { JsonObject, WorkflowRun, WorkflowRunError, WorkflowStepType } from "@kisi-workflow/shared";

import type { WorkflowRunRepository } from "../db/workflow-run-repository.js";
import { EngineValidationError, StepFailedError } from "./errors.js";
import { filterMatches } from "./filter.js";
import { executeHttpRequest } from "./http-request.js";
import type { TemplateBindings } from "./template.js";
import { applyTransform } from "./transform.js";

export const WORKFLOW_DEADLINE_MS = 25_000;

export type ExecuteWorkflowInput = {
  workflowId: string;
  steps: unknown;
  requestBody: unknown;
};

export type ExecuteWorkflowDeps = {
  runRepository: WorkflowRunRepository;
  fetchImpl?: typeof fetch;
  now?: () => Date;
  sleep?: (ms: number) => Promise<void>;
  random?: () => number;
  allowPrivateUrls?: boolean;
  generateId?: () => string;
  deadlineMs?: number;
};

function assertNever(value: never): never {
  throw new Error(`unexpected step: ${JSON.stringify(value)}`);
}

function failureOf(error: unknown, stepType: WorkflowStepType): Omit<WorkflowRunError, "stepIndex"> {
  if (error instanceof StepFailedError) {
    const message = error.message.length > 0 ? error.message : "step failed";
    if (error.httpStatus === undefined) {
      return { stepType: error.stepType, message };
    }
    return { stepType: error.stepType, message, httpStatus: error.httpStatus };
  }
  const message = error instanceof Error && error.message.length > 0 ? error.message : "step failed";
  return { stepType, message };
}

export async function executeWorkflow(
  input: ExecuteWorkflowInput,
  deps: ExecuteWorkflowDeps,
): Promise<WorkflowRun> {
  const stepsResult = WorkflowStepsSchema.safeParse(input.steps);
  const bodyResult = JsonObjectSchema.safeParse(input.requestBody);
  if (!stepsResult.success || !bodyResult.success) {
    throw new EngineValidationError();
  }

  const now = deps.now ?? (() => new Date());
  const started = now();
  const deadlineMs = deps.deadlineMs ?? WORKFLOW_DEADLINE_MS;
  const deadlineAt = started.getTime() + deadlineMs;
  const runId = deps.generateId?.() ?? randomUUID();
  const bindings: TemplateBindings = {
    workflow_id: input.workflowId,
    run_id: runId,
  };
  const requestBody = bodyResult.data;
  let ctx: JsonObject = structuredClone(requestBody);

  const finish = async (
    status: WorkflowRun["status"],
    error: WorkflowRunError | null,
    finalCtx: JsonObject,
  ): Promise<WorkflowRun> => {
    return deps.runRepository.create({
      id: runId,
      workflowId: input.workflowId,
      status,
      error,
      startedAt: started.toISOString(),
      finishedAt: now().toISOString(),
      requestBody: structuredClone(requestBody),
      finalCtx: structuredClone(finalCtx),
    });
  };

  for (const [index, step] of stepsResult.data.entries()) {
    if (now().getTime() >= deadlineAt) {
      return finish("failed", {
        stepIndex: index,
        stepType: step.type,
        message: "workflow time limit exceeded",
      }, ctx);
    }

    try {
      if (step.type === "transform") {
        ctx = applyTransform(step, ctx, bindings);
      } else if (step.type === "filter") {
        if (!filterMatches(step, ctx)) {
          return finish("skipped", null, ctx);
        }
      } else if (step.type === "http_request") {
        await executeHttpRequest(step, ctx, {
          fetchImpl: deps.fetchImpl ?? fetch,
          sleep: deps.sleep,
          random: deps.random,
          allowPrivateUrls: deps.allowPrivateUrls,
          bindings,
          now,
          deadlineAt,
        });
      } else {
        assertNever(step);
      }
    } catch (error) {
      const failure = failureOf(error, step.type);
      return finish("failed", { stepIndex: index, ...failure }, ctx);
    }
  }

  return finish("success", null, ctx);
}

